import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Before the original volatile publication; all earlier combat validation and SQL remain unchanged. */
public final class SourceOtherControlMethods {
 static final String P="local/lito381/server/",RULES=P+"CombatRules",N=P+"NativeSourceOtherControls";
 static void patch(ClassNode c){int count=0;for(var m:c.methods)for(var n:m.instructions.toArray())if(n instanceof FieldInsnNode f&&f.getOpcode()==PUTSTATIC&&f.owner.equals(RULES)&&f.name.equals("current")){if(!m.name.equals("load"))throw new AssertionError("only original startup publication");m.instructions.insertBefore(f,new MethodInsnNode(INVOKESTATIC,N,"prepare","(L"+RULES+"$Snapshot;)L"+RULES+"$Snapshot;",false));count++;}if(count!=1)throw new AssertionError("one startup publication");}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[1])){var old=FreezeAcceptedMethods.read(base,RULES);var c=FreezeAcceptedMethods.read(base,RULES);patch(c);byte[] bytes=FreezeAcceptedMethods.bytes(c,false);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(RULES+".class");Files.createDirectories(p.getParent());Files.write(p,bytes);}else try(var jar=new JarFile(a[2])){var actual=FreezeAcceptedMethods.read(jar,RULES);if(!Arrays.equals(bytes,FreezeAcceptedMethods.bytes(actual,false)))throw new AssertionError("exact publication port");int count=0;for(var m:actual.methods)for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(N)){if(!m.name.equals("load")||!call.name.equals("prepare"))throw new AssertionError("unexpected control port");m.instructions.remove(call);count++;}if(count!=1||!Arrays.equals(FreezeAcceptedMethods.bytes(old,false),FreezeAcceptedMethods.bytes(actual,false)))throw new AssertionError("complete original rules class inverse");var names=new HashSet<String>();int changed=0;for(var e:Collections.list(base.entries())){names.add(e.getName());var following=jar.getJarEntry(e.getName());if(following==null)throw new AssertionError("removed archive entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(following).readAllBytes())){if(!e.getName().equals(RULES+".class"))throw new AssertionError("unrelated archive class");changed++;}}var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());if(changed!=1||!fresh.equals(Set.of(N+".class",N+"$Snapshot.class",P+"NativeSourceDisplayPlan.class",P+"NativeSourceDisplayPlan$Effect.class",P+"NativeSourceDisplayPlan$Settings.class")))throw new AssertionError("only readonly settings and pure display plan added");}}System.out.println("PASS one original pre-publication Source reader; full original rules/archive inverse, no numeric/HP/SQL change");}
}
